import fitz, numpy as np
d=fitz.open('eprint/mAp_eps_plt_allbounds.pdf')
p=d[0]
def tolog(pt):
    x,y=pt
    return (-16+(x-114.5)/33.4786, -11+(378.5-y)/29.65)

targets={
 'purple_solid':((0.502,0.0,0.502),'[] 0'),
 'blue_solid':((0.0,0.0,1.0),'[] 0'),
 'green_solid':((0.0,0.502,0.0),'[] 0'),
 'green_dot1':((0.0,0.502,0.0),'[ 2.43 4.0095 ] 0'),
 'green_dot2':((0.0,0.502,0.0),'[ 2.65 4.3725 ] 0'),
 'orange_solid':((1.0,0.647,0.0),'[] 0'),
 'red_solid':((1.0,0.0,0.0),'[] 0'),
 'red_dot1':((1.0,0.0,0.0),'[ 2.43 4.0095 ] 0'),
 'red_dot2':((1.0,0.0,0.0),'[ 2.65 4.3725 ] 0'),
}
rev={v:k for k,v in targets.items()}
paths={}
for dr in p.get_drawings():
    col=dr['color']
    if col is None: continue
    key=(tuple(round(c,3) for c in col), dr['dashes'])
    if key not in rev: continue
    name=rev[key]
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            if not pts: pts.append(it[1])
            pts.append(it[2])
        elif it[0]=='c':
            if not pts: pts.append(it[1])
            pts.append(it[4])
    if pts:
        paths.setdefault(name,[]).append([tolog(pt) for pt in pts])

for name, plist in paths.items():
    print(f"== {name}: {len(plist)} paths")
    for pp in plist:
        xs=[a for a,b in pp]; ys=[b for a,b in pp]
        print(f"   n={len(pp)} x[{min(xs):.2f},{max(xs):.2f}] y[{min(ys):.2f},{max(ys):.2f}] start=({pp[0][0]:.2f},{pp[0][1]:.2f}) end=({pp[-1][0]:.2f},{pp[-1][1]:.2f})")
